/// capability — hashed into `secret-hash`, never stored raw), and the readers
/// (each a partial arg tree, already resolved client-side to name → oid).
#[derive(Clone)]
pub(crate) struct Grant {
    name: String,
    value: String,
    entropy: String,
    readers: Vec<BTreeMap<String, String>>,
}

